"""Generate fixtures."""

import os
import json
import math
import struct

# Get the file path:
FILE = os.path.realpath(__file__)

# Extract the directory in which this file resides:
DIR = os.path.dirname(FILE)


def f32(val):
    """Cast a float to float32 precision.

    # Arguments

    * `val`: value to cast

    # Returns

    Float32 representation.
    """
    try:
        return struct.unpack('f', struct.pack('f', val))[0]
    except OverflowError:
        if val > 0:
            return float('inf')
        return float('-inf')


def gen(x, name):
    """Generate fixture data and write to file.

    # Arguments

    * `x`: domain
    * `name::str`: filepath of the output file

    # Examples

    ``` python
    python> x = linspace(-10.0, 10.0, 2003)
    python> gen(x, './data.json')
    ```
    """
    y = []
    x_f32 = []
    for val in x:
        val_32 = f32(val)
        x_f32.append(val_32)
        try:
            expected = math.sinh(val_32)
            y.append(f32(expected))
        except OverflowError:
            if val > 0:
                y.append(float('inf'))
            else:
                y.append(float('-inf'))
    data = {
        "x": x_f32,
        "expected": y
    }

    # Based on the script directory, create an output filepath:
    filepath = os.path.join(DIR, name)

    # Write the data to the output filepath as JSON:
    with open(filepath, "w", encoding="utf-8") as outfile:
        json.dump(data, outfile)


def linspace(start, stop, num):
    """Generate linearly spaced numbers.

    # Arguments

    * `start`: start value
    * `stop`: stop value
    * `num`: number of values

    # Returns

    List of linearly spaced numbers.
    """
    if num == 1:
        return [float(start)]
    step = (stop - start) / (num - 1)
    return [start + i * step for i in range(num)]


def main():
    """Generate fixture data."""
    x = linspace(-10.0, 10.0, 2003)
    gen(x, "data.json")

    x = linspace(-88.0, 88.0, 2003)
    gen(x, "large.json")

    x = linspace(-1.0, 1.0, 2003)
    gen(x, "small.json")


if __name__ == "__main__":
    main()
